python -c "
import toolz
from toolz.functoolz import num_required_args, has_keywords

def should_curry(func):
    if not callable(func) or isinstance(func, toolz.curry):
        return False
    nargs = num_required_args(func)
    if nargs is None or nargs > 1:
        return True
    return nargs == 1 and has_keywords(func)

for name in ['apply', 'compose_left', 'compose', 'comp', 'pipe', 'identity', 'thread_first', 'thread_last', 'curry', 'peek', 'peekn', 'get_config_from_root']:
    func = getattr(toolz, name, None)
    if func is None:
        print(f'{name}: NOT FOUND')
    else:
        nargs = num_required_args(func)
        has_kw = has_keywords(func)
        sc = should_curry(func)
        print(f'{name}: should_curry={sc}, nargs={nargs}, has_keywords={has_kw}, type={type(func).__name__}')
"
